ValidationRule.errorConditionFormula:
AND(
    NOT(
        OR(
            RecordType.DeveloperName = "Consulta",
            RecordType.DeveloperName = "Reclamo",
            RecordType.DeveloperName = "Solicitud"
        )
    ),
    NOT(
        OR(
            Account.BillingCountry = "Brazil",
            Account.BillingCountry = "Paraguay"
        )
    ),
    OR(
        ISPICKVAL(Status, "Closed"),
        ISPICKVAL(Status, "Closure Pending")
    ),
    NOT(
        OR(
            ISPICKVAL(Type, "Master Data"),
            ISPICKVAL(Type, "EDI")
        )
    ),
    NOT(
        AND(
            ISPICKVAL(PMC_SS_IssueReason__c, "MDM Verification"),
            ISPICKVAL(Type, "Internal")
        )
    ),
    ISBLANK(TEXT(PMC_SS_AtFaultParty__c)),
    RecordType.DeveloperName = "PMC_SS_CaseGeneral"
)
